#!/usr/bin/env bash
# Third-party notices for the two shipped binaries (rfc/058), generated by the source's own
# validation/generate_rust_notices.py for one target triple. Only the three distributable files
# reach <out>; the generator's logs, metadata and inventory stay on the runner.
#
# The generator reads `cargo metadata --offline` for both workspaces and every platform, so both
# lockfiles are fetched in full first: a build fetches only its own target's crates.
#
# Usage: bash ci/notices.sh <source checkout> <target triple> <out dir>
set -euo pipefail

source_dir="$(cd "$1" && pwd)"
triple="$2"
out="$3"
work="$(mktemp -d)"

(cd "$source_dir" && cargo fetch --locked --quiet)
(cd "$source_dir/desktop" && cargo fetch --locked --quiet)

# Git Bash hands out /c/... paths; Python on Windows needs C:\...
native() { if command -v cygpath >/dev/null 2>&1; then cygpath -w "$1"; else echo "$1"; fi; }
about="$(native "$(command -v cargo-about)")"

for scope in cli desktop; do
    python "$(native "$source_dir/validation/generate_rust_notices.py")" \
        --cargo-about "$about" --target "$triple" --scope "$scope" --output "$(native "$work/$scope")"
done

mkdir -p "$out"
cp "$work/cli/RUST-DEPENDENCY-NOTICES.txt" \
   "$work/desktop/DESKTOP-DEPENDENCY-NOTICES.txt" \
   "$work/desktop/RUST-LIBRARY-COPYRIGHT.html" \
   "$out/"
ls -l "$out"
